        Assert.NotNull(lastVisited);
        Assert.True(DateTime.TryParse(lastVisited, out var lastVisitedUtc));
        Assert.True(lastVisitedUtc >= beforeRedirectUtc && lastVisitedUtc <= afterRedirectUtc);
    }

